import{_ as o,l as s,o as e,c as i,v as r,p as n,x as t,d,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"华莱士树与进位保存","description":"","frontmatter":{"title":"华莱士树与进位保存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wallace-carry-save.md","filePath":"cs/wallace-carry-save.md","lastUpdated":1789023840000}'),h={name:"cs/wallace-carry-save.md"};function p(C,a,E,_,m,u){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="华莱士树与进位保存" tabindex="-1">华莱士树与进位保存 <a class="header-anchor" href="#华莱士树与进位保存" aria-label="Permalink to &quot;华莱士树与进位保存&quot;">​</a></h1><div class="epigraph"><p>许多个数相加时，不必每一步都等进位走完：全加器可以先把三数压成两数，进位留到最后一次传播。</p><footer>—— 据 Wallace, A Suggestion for a Fast Multiplier, IEEE Trans. Electron. Comput. 1964；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/booth-multiplier">上一课</a>把补码乘的部分积条数收少了，但条数仍大于 2。组成课的<a href="/cs/array-multiplier">阵列乘法</a>点到进位保留，没有把压缩树画完。缺口是：<strong>多操作数加法</strong>的延迟——若每层都用行波/CLA 把进位走完，Booth 省下的条数会被进位链吃回去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个已对齐的部分积要加成一个 \\(2n\\) 位积。<a href="/cs/adder-cla">CLA</a> 擅长两个数；三个以上若串成「加完再加」，每层都付一次进位传播。进位保存加法器（CSA）：一位全加器吃三比特，吐出本位和与进位，<strong>进位不链到同一层邻位</strong>，只接到下一层更高权。三数变两数（3:2 压缩）。缺口不是新的乘法语义，而是把部分积高度按对数层压到 2，再交给一次 CLA。</p><p>Wallace 树：每列独立用全加器尽量压；Dadda 树更吝啬全加器、层数策略不同。本课钉 CSA 与 Wallace 形状，不把 Dadda 的每列定额写成作业。</p><h3 id="进位保存不是「丢掉进位」" tabindex="-1">进位保存不是「丢掉进位」 <a class="header-anchor" href="#进位保存不是「丢掉进位」" aria-label="Permalink to &quot;进位保存不是「丢掉进位」&quot;">​</a></h3><p>CSA 的进位被显式保存为另一向量，最终必须与和向量做一次常规加。把 CSA 理解成近似加法，积的低位会错。它节省的是<strong>中间层的传播延迟</strong>，不是精度。</p><p><span class="marginnote">Wallace 1964 的建议是树形压缩。Harris 用 4:2 压缩器作现代积木（两个 CSA 叠成）。Hennessy/Patterson 把乘法器延迟当成整数单元的关键路径候选，不在本课展开流水线切拍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>部分积按权排成点图。同一权三位进一个全加器：和留本列，进位进右列（更高权）下一层。重复直到每列至多两点，再用 <a href="/cs/adder-cla">CLA</a> 收尾。4:2 压缩器把五输入（含进位入）压成和与进位，便于规则布局。</p>',11)),(e(),n(A,null,{default:t(()=>[c(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PP%5B%22Booth%20%E9%83%A8%E5%88%86%E7%A7%AF%22%5D%20--%3E%20CSA%5B%223%3A2%20%2F%204%3A2%20%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20CSA%20--%3E%20TWO%5B%22%E5%92%8C%E5%90%91%E9%87%8F%20%2B%20%E8%BF%9B%E4%BD%8D%E5%90%91%E9%87%8F%22%5D%0A%20%20TWO%20--%3E%20CLA%5B%22%E6%9C%AB%E7%BA%A7%20CLA%22%5D%0A%20%20CLA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%99%A4%E6%B3%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>层数约为 \\(\\Theta(\\log_{1.5} h)\\)，\\(h\\) 是部分积高度。Booth 降低 \\(h\\)，树变浅；两者正交：编码管条数，CSA 管怎么加。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>组合乘法器的关键路径 = 部分积生成 + 压缩树 + 末级 CLA。后课除法是另一条迭代或阵列通路，不共用这棵树的中间和。流水线可以把 CSA 层切开，那是时序问题，功能上仍是同一压缩。本课不把 FPGA DSP 块的内部流水线当成 CSA 的定义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲除法、不把浮点对阶加法器的对齐移位画进来。浮点尾数乘会再用同一棵树，但指数与规格化是后课。也不引入冗余数系的完整理论，CSA 只作为延迟手段。</p><p>后课默认：多操作数加用 CSA 压到两操作数，再一次传播进位；乘法器延迟由树深而不是 \\(h\\) 次 CLA 决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Booth 减少部分积；CSA/华莱士树减少中间进位传播。</li><li>3:2 把三数变成和与进位两向量；末级仍要 CLA。</li><li>不丢进位，只推迟传播。</li><li>出处：Wallace, <em>IEEE TEC</em>, 1964；Harris and Harris；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const B=o(h,[["render",p]]);export{f as __pageData,B as default};
